ProcessStepPayload = Annotated[
    EvacuationStepPayload
    | LeakCheckStepPayload
    | PurgeStepPayload
    | PretreatmentStepPayload
    | RampStepPayload
    | TemperatureStabilizationStepPayload
    | GrowthStepPayload
    | PostAnnealStepPayload
    | CoolingStepPayload
    | VentStepPayload
    | UnloadStepPayload,
    Field(discriminator="stage_type"),
]


class ProcessStepsPayload(V2PayloadBase):
    items: list[ProcessStepPayload] = Field(default_factory=list)

    # Cross-entity condition 装置Setup.外场装置≠无 for field_params is enforced
    # in v2_experiment_service; generated module models see only one payload.



class ProcessEventItemPayload(V2PayloadBase):
    event_part: str | None = None
    occurred_at: datetime | None = None
    abort_reason: Literal['equipment_alarm', 'manual_stop', 'planned_completion'] | None = None
    description_action: str | None = None

    @field_validator('occurred_at', mode="before")
    @classmethod
    def _offset_datetime(cls, value: Any) -> Any:
        return None if value is None else _normalize_datetime(value)


class ProcessEventsPayload(V2PayloadBase):
    items: list[ProcessEventItemPayload] = Field(default_factory=list)



class PvdPayload(V2PayloadBase):
    target_lot_ref: MaterialLotReferencePayload | None = None
    target_substrate_distance_mm: Annotated[float, Field(strict=True, allow_inf_nan=False, gt=0)] | None = None
    power_bias: Annotated[float, Field(strict=True, allow_inf_nan=False)] | None = None
    plasma_gas_pressure: PlasmaGasPressureValue | None = None
    presputter_shutter: Annotated[float, Field(strict=True, allow_inf_nan=False, gt=0)] | None = None
    deposition_rate_nm_s: Annotated[float, Field(strict=True, allow_inf_nan=False, gt=0)] | None = None


V2_MODULE_PAYLOAD_MODELS: dict[str, type[BaseModel]] = {
    "basic_info": BasicInfoPayload,
    "target_product": TargetProductPayload,
    "equipment": EquipmentPayload,
    "precursors": PrecursorsPayload,
    "substrates": SubstratesPayload,
    "process_steps": ProcessStepsPayload,
    "process_events": ProcessEventsPayload,
    "pvd": PvdPayload,
}


def validate_v2_module_payload(
    module_key: str, payload_json: dict[str, Any]
) -> dict[str, Any]:
    model = V2_MODULE_PAYLOAD_MODELS.get(module_key)
    if model is None:
        raise ValueError(f"Unsupported cvd_v2 module: {module_key}")
    return model.model_validate(_normalize_payload(payload_json)).model_dump(
        mode="json", exclude_none=False
    )


V2Payload = (
    BasicInfoPayload
    | TargetProductPayload
    | EquipmentPayload
    | PrecursorsPayload
    | SubstratesPayload
    | ProcessStepsPayload
    | ProcessEventsPayload
    | PvdPayload
)
